export const ARMS: Readonly<Record<string, readonly (readonly [number, number])[]>> = {
  down: [[0, 4], [1, 4], [0, 5], [1, 5]],
  up1: [[0, 3], [1, 3], [0, 4], [1, 4]],
  up2: [[0, 2], [1, 2], [0, 3], [1, 3]],
