  fun_stone1: s(['...GWW..', '..GWWWG.', '.GWWGGGD', 'GWGGGGGD', 'GGGGGGDD', '.DDDDDD.']),
  fun_stone2: s(['...GGW..', '..GWWGG.', '.GGGGWGD', 'GGGWGGGD', 'GDGGGDDD', '.DDDDDD.']),
