  fun_flower2: s(['.....', '.WYW.', '.WWW.', '..E..', '.EE..', '..EE.', '..E..', '..E..']),
  fun_flower3: s(['.WWW.', 'WWYWW', '.WWW.', '..E..', '.EE..', '..EE.', '..E..', '..E..']),
