  fun_ball2: s(['WBB', 'BBB']),
  // Seifenblasenstab (6×9): grüner Ring, cremefarbener Griff (2 breit), brauner Knauf
  fun_wand1: s(['.EEEE.', 'E....E', 'E....E', 'E....E', '.EEEE.', '..CC..', '..CC..', '..CC..', '..RR..']),
