/** Fensterchen (10x6) mit Titelpunkten und zwei laufenden grünen Zeilen: k = 0 bis 5 schiebt die Zeilen weiter (halbe Zeile, dann neue Länge). */
const MLINES = [5, 3, 6, 2, 4, 6, 3]
function miniWin(k: number): PropSprite {
