  rect(g, 1, 3, 2, 3, col)
  if (b === 1) put(g, 1, 5, 'W')
  if (b === 2) put(g, 2, 4, 'W')
  if (b === 3) put(g, 1, 3, 'W')
  if (b === 3) put(g, 2, 2, 'W')
  return spr(rowsOf(g))
}

